/**
 * Import NoBooze store artwork from the local app repo into public/apps.
 *
 * NoBooze's App Store creative frames are generated by its own Fastlane
 * pipeline, so those are the canonical source — re-run this after a screenshot
 * refresh rather than cropping anything by hand. The source repo is resolved
 * from this machine and skipped with a warning when absent, so `npm run build`
 * never depends on it.
 *
 *   npm run shots
 *
 * GemGame (~/GemGame/fastlane/store_screenshots/creative/en-GB) and Fleet
 * Commander (~/gamesdev/fastlane/store_screenshots/creative/default/en-GB) are
 * deliberately NOT imported. Their committed posters come from an earlier
 * creative pass that reads better at portfolio scale — mid-cascade action and a
 * clean 09:41 status bar — so they are pinned by hand. Re-point this script at
 * them only after checking the newer frames actually look better.
 */
import sharp from 'sharp';
import { existsSync, statSync } from 'node:fs';
import { homedir } from 'node:os';
import { join, dirname, basename } from 'node:path';
import { fileURLToPath } from 'node:url';

const HOME = homedir();
const OUT = join(dirname(fileURLToPath(import.meta.url)), '..', 'public', 'apps');
const NOBOOZE = join(HOME, 'fiveFive/NoBooze/fastlane/screenshots/en-GB');

/** Width every store poster is normalised to. Portrait 1320x2868 sources land
 *  at 760x1651 — 2x the widest rendered poster (17rem ≈ 272px). */
const POSTER_WIDTH = 760;

/** NoBooze gets a single poster beside its editorial "design premise" panel,
 *  so only the dashboard frame is imported. Swap the source here to change it. */
const SHOTS = [{ from: join(NOBOOZE, '01-dashboard.png'), to: 'nobooze-dashboard.webp' }];

let written = 0;
let skipped = 0;

for (const shot of SHOTS) {
  const target = join(OUT, shot.to);
  if (!existsSync(shot.from)) {
    console.warn(`skip  ${shot.to.padEnd(28)} source missing: ${shot.from}`);
    skipped += 1;
    continue;
  }
  const info = await sharp(shot.from)
    .resize({ width: POSTER_WIDTH, kernel: 'lanczos3' })
    .webp({ quality: 82, effort: 6 })
    .toFile(target);
  console.log(
    `write ${basename(target).padEnd(28)} ${info.width}x${info.height}  ` +
      `${(statSync(target).size / 1024).toFixed(0)}KB`,
  );
  written += 1;
}

console.log(`\n${written} written, ${skipped} skipped.`);
